static void mkdir_p(const char *path){
    if(!path||!path[0]) return;
    char tmp[PATH_MAX*2];
    strncpy(tmp,path,sizeof(tmp)-1); tmp[sizeof(tmp)-1]=0;
    size_t len=strlen(tmp);
    while(len>1 && tmp[len-1]=='/'){tmp[len-1]=0; len--;}
    if(len==0) return;
    char built[PATH_MAX*2]="";
    char *p=tmp;
    if(tmp[0]=='/'){strcpy(built,"/"); p=tmp+1;}
    char *save=NULL;
    // manual tokenize to handle consecutive /?
    char *tok=strtok_r(p,"/",&save);
    while(tok){
        if(strcmp(built,"/")==0) snprintf(built,sizeof(built),"/%s",tok);
        else if(built[0]==0) snprintf(built,sizeof(built),"%s",tok);
        else { size_t bl=strlen(built); snprintf(built+bl,sizeof(built)-bl,"/%s",tok); }
        mkdir(built,0755);
        tok=strtok_r(NULL,"/",&save);
    }
}

