    unsigned long long tenths = (bytes*10)/div; // careful overflow for large bytes? bytes up to ~1T, *10 fits in 64? 1T*10=10T < 2^64. Good. For larger (P/E), might overflow? But unlikely for test files (small). For volume (999G), 999G*10=9990G < 2^64. Good.
    unsigned long long whole = tenths/10;
    unsigned long long frac = tenths%10;
    if(frac==0) snprintf(out,outsz,"%llu%c",whole,units[ui]);
    else snprintf(out,outsz,"%llu.%llu%c",whole,frac,units[ui]);
